func:
// Step 1: discover which entities to count. filter_entity_id takes explicit
// ids -- the REST history endpoint does NOT accept wildcards -- so the ids
// come from /api/states, the same call the HA tab already makes.
var base = (env.get('HA_URL') || '').replace(/\/+$/, '');
var token = env.get('HA_TOKEN');
if (!base || !token) {
  node.status({fill:'red',shape:'ring',text:'missing HA_URL/HA_TOKEN'});
  var miss = [];
  if (!base) { miss.push('HA_URL'); }
  if (!token) { miss.push('HA_TOKEN'); }
  msg._error = 'missing ' + miss.join(', ') + ' in /root/.node-red/.env';
  msg.topic = 'ha/error';
  return [null, null, msg];
}
msg.method = 'GET';
msg.ret = 'obj';
msg.url = base + '/api/states';
msg.headers = {Authorization: 'Bearer ' + token};
msg.rejectUnauthorized = false;
node.status({fill:'blue',shape:'dot',text:'listing entities'});
return [msg, null];

// Step 2: turn the states list into a 24h history query.
if (msg.error || !msg.statusCode || msg.statusCode >= 400) {
  node.status({fill:'red',shape:'ring',text:'states unreachable'});
  msg._error = msg.error ? String(msg.error.message || msg.error)
    : ('HTTP ' + (msg.statusCode || '?'));
  msg.topic = 'ha/error';
  return [null, null, msg];
}
var DOMAINS = ['light','switch','media_player','cover','lock','climate','fan'];
var all = Array.isArray(msg.payload) ? msg.payload : [];
var ids = [];
for (var i = 0; i < all.length; i++) {
  var e = all[i];
  if (!e || !e.entity_id) { continue; }
  var dom = e.entity_id.split('.')[0];
  // Explicit membership test. The worker's `!(indexOf) >= 0` inverted this.
  if (DOMAINS.indexOf(dom) < 0) { continue; }
  if (e.state === 'unavailable' || e.state === 'unknown') { continue; }
  ids.push(e.entity_id);
}
if (ids.length === 0) {
  node.status({fill:'yellow',shape:'ring',text:'no controllable entities'});
  msg.payload = {severity: 'warning',
                 message: 'Activity: no controllable entities to count'};
  return [null, null, msg];
}
// Cap the id list so the query string stays well under any proxy limit.
ids = ids.slice(0, 120);
var base = (env.get('HA_URL') || '').replace(/\/+$/, '');
var since = new Date(Date.now() - 24 * 3600 * 1000)
  .toISOString().slice(0, 19) + 'Z';
msg.method = 'GET';
msg.ret = 'obj';
msg.url = base + '/api/history/period/' + since
  + '?filter_entity_id=' + encodeURIComponent(ids.join(','))
  + '&minimal_response&no_attributes&significant_changes_only=0';
msg.headers = {Authorization: 'Bearer ' + (env.get('HA_TOKEN') || '')};
msg.rejectUnauthorized = false;
msg._entityCount = ids.length;
node.status({fill:'blue',shape:'dot',text:ids.length + ' entities'});
return [msg, null];

// Step 3: count state changes into 24 hourly buckets.
// /api/history/period returns one array PER ENTITY (time-ordered states).
if (msg.error || !msg.statusCode || msg.statusCode >= 400) {
  node.status({fill:'red',shape:'ring',text:'history unreachable'});
  msg._error = msg.error ? String(msg.error.message || msg.error)
    : ('HTTP ' + (msg.statusCode || '?'));
  msg.topic = 'ha/error';
  return [null, msg];
}
var perEntity = Array.isArray(msg.payload) ? msg.payload : [];
var now = Date.now();
var HOUR = 3600000;
var buckets = [];
for (var b = 0; b < 24; b++) { buckets.push(0); }
var total = 0;
for (var i = 0; i < perEntity.length; i++) {
  var series = perEntity[i];
  if (!Array.isArray(series)) { continue; }
  for (var j = 0; j < series.length; j++) {
    var st = series[j];
    if (!st || !st.last_changed) { continue; }
    var t = new Date(st.last_changed).getTime();
    if (isNaN(t)) { continue; }
    var age = Math.floor((now - t) / HOUR);   // 0 = the current hour
    if (age < 0 || age > 23) { continue; }
    buckets[age] += 1;
    total += 1;
  }
}
// Oldest -> newest, which is the order both the x axis and the tooltip assume.
var points = [];
for (var age = 23; age >= 0; age--) {
  points.push({t: now - age * HOUR, y: buckets[age]});
}
node.status({fill:'green',shape:'dot',text: total + ' changes / 24h'});
return [{payload: points, _total: total,
         _entities: (msg._entityCount || 0)},
        null];

// Catch-node feed: a node failure MUST surface as a critical banner.
if (msg.error) {
  var src = (msg.error.source && msg.error.source.name)
    ? msg.error.source.name : 'integration';
  var emsg = String(msg.error.message || 'failed').slice(0, 110);
  node.status({fill: 'red', shape: 'ring', text: 'node error'});
  msg.payload = {severity: 'critical', message: src + ' failed: ' + emsg};
  return msg;
}
// Activity banner: chart freshness + reachability.
// Both builders tag failures with topic 'ha/error' + msg._error, so an
// unreachable HA is CRITICAL here -- never a silent 'awaiting first result'.
if (msg.topic === 'ha/error' || msg._error) {
  node.status({fill: 'red', shape: 'ring', text: 'history down'});
  msg.payload = {severity: 'critical',
    message: 'Activity history unavailable: '
             + String(msg._error || '').slice(0, 100)};
  return msg;
}
// A builder may hand over a finished banner (e.g. 'no controllable entities').
if (msg.payload && msg.payload.severity && msg.payload.message) {
  return msg;
}
var total = (msg.payload && typeof msg.payload._total === 'number')
  ? msg.payload._total : null;
var ents = (msg.payload && typeof msg.payload._entities === 'number')
  ? msg.payload._entities : 0;
var sev;
var text;
if (total === null) {
  sev = 'info';
  text = 'Activity: awaiting first result';
} else if (total === 0) {
  sev = 'info';
  text = 'Activity: no state changes in 24h (' + ents + ' entities watched)';
} else {
  sev = 'ok';
  text = total + ' state changes from ' + ents + ' entities in the last 24h';
}
node.status({fill: sev === 'ok' ? 'green' : (sev === 'critical' ? 'red' : 'yellow'), shape: 'dot', text: sev});
msg.payload = {severity: sev, message: text};
return msg;
